DROP TABLE IF EXISTS tower_data_quality; DROP TABLE IF EXISTS tower_monthly_clean; DROP VIEW IF EXISTS v_tower_monthly_kpi;
CREATE TABLE tower_data_quality AS
WITH s AS (SELECT rowid raw_row_id,tower_id,region_id,CASE WHEN UPPER(TRIM(region_name))='DHAKA' THEN 'Dhaka' WHEN UPPER(TRIM(region_name)) IN ('CHATTOGRAM','CHITTAGONG') THEN 'Chattogram' WHEN UPPER(TRIM(region_name))='SYLHET' THEN 'Sylhet' WHEN UPPER(TRIM(region_name))='RAJSHAHI' THEN 'Rajshahi' WHEN UPPER(TRIM(region_name))='KHULNA' THEN 'Khulna' WHEN UPPER(TRIM(region_name)) IN ('BARISHAL','BARISAL') THEN 'Barishal' WHEN UPPER(TRIM(region_name))='RANGPUR' THEN 'Rangpur' WHEN UPPER(TRIM(region_name))='MYMENSINGH' THEN 'Mymensingh' END region_name_std,tower_type,month_raw,revenue,active_tenants,available_slots,downtime_hours,CASE WHEN month_raw LIKE '____/__/__' THEN REPLACE(month_raw,'/','-') WHEN month_raw LIKE '__/__/____' THEN SUBSTR(month_raw,7,4)||'-'||SUBSTR(month_raw,1,2)||'-'||SUBSTR(month_raw,4,2) WHEN month_raw LIKE '___-____' THEN SUBSTR(month_raw,5,4)||'-'||CASE UPPER(SUBSTR(month_raw,1,3)) WHEN 'JAN' THEN '01' WHEN 'FEB' THEN '02' WHEN 'MAR' THEN '03' WHEN 'APR' THEN '04' WHEN 'MAY' THEN '05' WHEN 'JUN' THEN '06' WHEN 'JUL' THEN '07' WHEN 'AUG' THEN '08' WHEN 'SEP' THEN '09' WHEN 'OCT' THEN '10' WHEN 'NOV' THEN '11' WHEN 'DEC' THEN '12' END||'-01' ELSE month_raw END month_std FROM tower_operations_raw), f AS (SELECT *,COUNT(*) OVER(PARTITION BY tower_id,month_std) duplicate_count,CASE WHEN revenue IS NULL OR revenue<0 THEN 1 ELSE 0 END bad_revenue_flag,CASE WHEN active_tenants IS NULL OR active_tenants<0 OR active_tenants>available_slots THEN 1 ELSE 0 END bad_tenancy_flag,CASE WHEN downtime_hours IS NULL OR downtime_hours<0 OR downtime_hours>24 THEN 1 ELSE 0 END bad_downtime_flag,CASE WHEN region_name_std IS NULL THEN 1 ELSE 0 END bad_region_flag,CASE WHEN date(month_std) IS NULL THEN 1 ELSE 0 END bad_date_flag FROM s) SELECT *,CASE WHEN duplicate_count>1 OR bad_revenue_flag=1 OR bad_tenancy_flag=1 OR bad_downtime_flag=1 OR bad_region_flag=1 OR bad_date_flag=1 THEN 1 ELSE 0 END has_quality_issue FROM f;
CREATE TABLE tower_monthly_clean AS
WITH s AS (SELECT rowid raw_row_id,tower_id,region_id,CASE WHEN UPPER(TRIM(region_name))='DHAKA' THEN 'Dhaka' WHEN UPPER(TRIM(region_name)) IN ('CHATTOGRAM','CHITTAGONG') THEN 'Chattogram' WHEN UPPER(TRIM(region_name))='SYLHET' THEN 'Sylhet' WHEN UPPER(TRIM(region_name))='RAJSHAHI' THEN 'Rajshahi' WHEN UPPER(TRIM(region_name))='KHULNA' THEN 'Khulna' WHEN UPPER(TRIM(region_name)) IN ('BARISHAL','BARISAL') THEN 'Barishal' WHEN UPPER(TRIM(region_name))='RANGPUR' THEN 'Rangpur' WHEN UPPER(TRIM(region_name))='MYMENSINGH' THEN 'Mymensingh' END region_name,tower_type,CASE WHEN month_raw LIKE '____/__/__' THEN REPLACE(month_raw,'/','-') WHEN month_raw LIKE '__/__/____' THEN SUBSTR(month_raw,7,4)||'-'||SUBSTR(month_raw,1,2)||'-'||SUBSTR(month_raw,4,2) WHEN month_raw LIKE '___-____' THEN SUBSTR(month_raw,5,4)||'-'||CASE UPPER(SUBSTR(month_raw,1,3)) WHEN 'JAN' THEN '01' WHEN 'FEB' THEN '02' WHEN 'MAR' THEN '03' WHEN 'APR' THEN '04' WHEN 'MAY' THEN '05' WHEN 'JUN' THEN '06' WHEN 'JUL' THEN '07' WHEN 'AUG' THEN '08' WHEN 'SEP' THEN '09' WHEN 'OCT' THEN '10' WHEN 'NOV' THEN '11' WHEN 'DEC' THEN '12' END||'-01' ELSE month_raw END month_std,revenue,operating_cost,active_tenants,available_slots,downtime_hours,incidents,maintenance_cost FROM tower_operations_raw), r AS (SELECT *,ROW_NUMBER() OVER(PARTITION BY tower_id,month_std ORDER BY CASE WHEN revenue IS NOT NULL AND revenue>=0 THEN 0 ELSE 1 END,CASE WHEN active_tenants BETWEEN 0 AND available_slots THEN 0 ELSE 1 END,CASE WHEN downtime_hours BETWEEN 0 AND 24 THEN 0 ELSE 1 END,raw_row_id) rn FROM s), b AS (SELECT tower_id,region_id,region_name,tower_type,date(month_std) month,CASE WHEN revenue>=0 THEN revenue END revenue_raw,operating_cost,CASE WHEN active_tenants BETWEEN 0 AND available_slots THEN active_tenants END active_tenants_raw,available_slots,CASE WHEN downtime_hours BETWEEN 0 AND 24 THEN downtime_hours END downtime_raw,incidents,maintenance_cost FROM r WHERE rn=1 AND date(month_std) IS NOT NULL AND region_name IS NOT NULL), i AS (SELECT *,COALESCE(revenue_raw,ROUND(AVG(revenue_raw) OVER(PARTITION BY tower_id ORDER BY month ROWS BETWEEN 1 PRECEDING AND 1 FOLLOWING),2)) revenue,COALESCE(active_tenants_raw,ROUND(AVG(active_tenants_raw) OVER(PARTITION BY tower_id ORDER BY month ROWS BETWEEN 1 PRECEDING AND 1 FOLLOWING))) active_tenants,COALESCE(downtime_raw,ROUND(AVG(downtime_raw) OVER(PARTITION BY tower_id ORDER BY month ROWS BETWEEN 1 PRECEDING AND 1 FOLLOWING),2)) downtime_hours FROM b) SELECT tower_id,region_id,region_name,tower_type,month,ROUND(revenue,2) revenue,ROUND(operating_cost,2) operating_cost,CAST(active_tenants AS INTEGER) active_tenants,available_slots,ROUND(downtime_hours,2) downtime_hours,incidents,ROUND(maintenance_cost,2) maintenance_cost,ROUND(1.0*active_tenants/NULLIF(available_slots,0),4) tenancy_rate,ROUND(revenue/NULLIF(active_tenants,0),2) revenue_per_tenant,ROUND(revenue-operating_cost,2) estimated_operating_margin FROM i WHERE revenue IS NOT NULL AND active_tenants IS NOT NULL AND downtime_hours IS NOT NULL;
CREATE VIEW v_tower_monthly_kpi AS SELECT *,LAG(revenue) OVER(PARTITION BY tower_id ORDER BY month) previous_revenue,ROUND(100.0*(revenue-LAG(revenue) OVER(PARTITION BY tower_id ORDER BY month))/NULLIF(LAG(revenue) OVER(PARTITION BY tower_id ORDER BY month),0),2) revenue_change_pct,LAG(active_tenants) OVER(PARTITION BY tower_id ORDER BY month) previous_tenants,active_tenants-LAG(active_tenants) OVER(PARTITION BY tower_id ORDER BY month) tenant_change,LAG(downtime_hours) OVER(PARTITION BY tower_id ORDER BY month) previous_downtime FROM tower_monthly_clean;
